package io.graphrag.core;
import java.time.Instant;
import java.util.*;
import static io.graphrag.core.Domain.*;
import static io.graphrag.core.Ports.*;

public final class Ingestion {
    private final Store store;private final DocumentParser parser;private final LanguageModel model;private final Embeddings embeddings;private final CommunityDetector detector;private final Settings cfg;
    public Ingestion(Store store,DocumentParser parser,LanguageModel model,Embeddings embeddings,CommunityDetector detector,Settings cfg){this.store=store;this.parser=parser;this.model=model;this.embeddings=embeddings;this.detector=detector;this.cfg=cfg;}
    public Corpus create(String name){Corpus c=new Corpus(UUID.randomUUID().toString(),name,Status.BUILDING,Instant.now(),model.offline()?"DETERMINISTIC":"LIVE",null,null);store.save(Snapshot.empty(c));return c;}
    public void process(String id,List<Input> inputs,ProgressSink sink){Snapshot old=store.read(id);String stage="parsing";long[] seq={0};List<Document> docs=new ArrayList<>();List<Passage> passages=new ArrayList<>();List<Chunk> chunks=new ArrayList<>();Map<String,Entity> entities=new TreeMap<>();Map<String,Relationship> rels=new TreeMap<>();List<Community> communities=new ArrayList<>();Map<String,List<Double>> vectors=new TreeMap<>();
        try {
            emit(sink,seq,stage,"Extracting document text",passages,entities,rels,communities,false);
            for(int d=0;d<inputs.size();d++){Input input=inputs.get(d);Parsed parsed=parser.parse(input);if(parsed.text().isBlank())throw new IllegalArgumentException("No readable text in "+input.name()+". Scanned PDFs require OCR before upload.");String docId=input.existingDocumentId()==null?Text.id(id,"doc",Integer.toString(d),input.name()):input.existingDocumentId();docs.add(new Document(docId,input.name(),input.mediaType(),Map.of()));int p=0;for(String text:Text.split(parsed.text(),cfg.passageSize(),cfg.overlap()))passages.add(new Passage(Text.id(docId,"passage",Integer.toString(p)),docId,input.name(),p++,text,parsed.location(),Map.of()));int n=0;for(String text:Text.split(parsed.text(),cfg.chunkSize(),Math.min(50,cfg.chunkSize()/10)))chunks.add(new Chunk(Text.id(docId,"chunk",Integer.toString(n)),docId,input.name(),n++,text,parsed.location(),List.of()));}
            stage="extraction";
            for(int p=0;p<passages.size();p++){Passage passage=passages.get(p);List<EntityDraft> drafts=model.entities(passage.text());merge(id,passage,drafts,model.relationships(passage.text(),drafts),entities,rels);store.save(snapshot(old.corpus(),docs,passages,entities,rels,communities,chunks,vectors));emit(sink,seq,stage,"Processed passage "+(p+1)+" of "+passages.size(),passages,entities,rels,communities,false);}
            stage="communities";for(Set<String> members:detector.detect(id,List.copyOf(entities.values()),List.copyOf(rels.values()))){var es=entities.values().stream().filter(e->members.contains(e.id())).toList();var rs=rels.values().stream().filter(r->members.contains(r.source())&&members.contains(r.target())).toList();Summary summary=model.summarize(es,rs);String cid=Text.id(id,"community",String.join(",",new TreeSet<>(members)));communities.add(new Community(cid,summary.title(),summary.text(),members,List.of()));}store.save(snapshot(old.corpus(),docs,passages,entities,rels,communities,chunks,vectors));emit(sink,seq,stage,"Formed "+communities.size()+" communities with at least three members",passages,entities,rels,communities,false);
            stage="indexing";for(Entity e:entities.values())vectors.put(e.id(),embeddings.embed(e.name()+" "+e.description()));for(int i=0;i<communities.size();i++){var c=communities.get(i);communities.set(i,new Community(c.id(),c.title(),c.summary(),c.members(),embeddings.embed(c.summary())));}for(int i=0;i<chunks.size();i++){var c=chunks.get(i);chunks.set(i,new Chunk(c.id(),c.documentId(),c.documentName(),c.ordinal(),c.text(),c.location(),embeddings.embed(c.text())));if(i%10==0)emit(sink,seq,stage,"Indexed "+(i+1)+" of "+chunks.size()+" vector chunks",passages,entities,rels,communities,false);}
            store.save(snapshot(old.corpus().state(Status.READY,null,null),docs,passages,entities,rels,communities,chunks,vectors));emit(sink,seq,"complete","Corpus is ready",passages,entities,rels,communities,true);
        }catch(Exception e){store.save(snapshot(old.corpus().state(Status.FAILED,stage,safeReason(e)),docs,passages,entities,rels,communities,chunks,vectors));emit(sink,seq,"error",stage+": "+safeReason(e),passages,entities,rels,communities,true);}
    }
    public static String safeReason(Exception e){if(e instanceof IllegalArgumentException)return e.getMessage()==null?"Invalid input":e.getMessage();return "Processing failed ("+e.getClass().getSimpleName()+"). Check server logs and model/database configuration, then create a new corpus.";}
    private static Snapshot snapshot(Corpus c,List<Document>d,List<Passage>p,Map<String,Entity>e,Map<String,Relationship>r,List<Community>co,List<Chunk>ch,Map<String,List<Double>>v){return new Snapshot(c,List.copyOf(d),List.copyOf(p),List.copyOf(e.values()),List.copyOf(r.values()),List.copyOf(co),List.copyOf(ch),Map.copyOf(v));}
    private static void emit(ProgressSink sink,long[] seq,String stage,String message,List<Passage>p,Map<String,Entity>e,Map<String,Relationship>r,List<Community>c,boolean terminal){sink.emit(new Progress(++seq[0],stage,message,p.size(),e.size(),r.size(),c.size(),terminal));}
    private static Set<String> union(Set<String>a,String p){Set<String>s=new TreeSet<>(a);s.add(p);return Set.copyOf(s);}
    private static String description(String a,String b){return a.contains(b)?a:a+"\n"+b;}
    public static void merge(String corpusId,Passage p,List<EntityDraft> drafts,List<RelationDraft> rs,Map<String,Entity> es,Map<String,Relationship> rels){
        for(var d:drafts){String normalized=Text.normalize(d.name());if(normalized.isEmpty())continue;String id=Text.id(corpusId,"entity",normalized);Entity old=es.get(id);String type=d.type()==null?"Unknown":d.type();String desc=d.description()==null?d.name():d.description();if(old==null)es.put(id,new Entity(id,d.name().trim(),type,desc,Set.of(p.id()),Map.of()));else es.put(id,new Entity(id,old.name(),old.type().compareTo(type)<=0?old.type():type,description(old.description(),desc),union(old.passageIds(),p.id()),old.attributes()));}
        for(var r:rs){String source=Text.id(corpusId,"entity",Text.normalize(r.source())),target=Text.id(corpusId,"entity",Text.normalize(r.target()));if(!es.containsKey(source)||!es.containsKey(target)||source.equals(target))continue;if(!Double.isFinite(r.weight())||r.weight()<=0)throw new IllegalArgumentException("Relationship weight must be positive and finite");String type=r.type()==null?"RELATED":r.type();String rid=Text.id(corpusId,source,target,type);Relationship old=rels.get(rid);rels.put(rid,new Relationship(rid,source,target,type,old==null?r.description():description(old.description(),r.description()),old==null?r.weight():Math.max(old.weight(),r.weight()),old==null?Set.of(p.id()):union(old.passageIds(),p.id())));}
    }
    /** Import an externally constructed graph with provenance; no extraction model call. */
    public void importGraph(Snapshot graph){Set<String> p=new HashSet<>(),e=new HashSet<>();graph.passages().forEach(x->p.add(x.id()));graph.entities().forEach(x->e.add(x.id()));for(Entity x:graph.entities())if(!p.containsAll(x.passageIds()))throw new IllegalArgumentException("Unknown supporting passage");for(Relationship r:graph.relationships())if(!e.contains(r.source())||!e.contains(r.target())||!p.containsAll(r.passageIds()))throw new IllegalArgumentException("Invalid relationship provenance");store.save(graph);}
    /** Rebuild derived data from retained source text, preserving document and passage identities. */
    public void replaceSource(String corpusId,String documentId,Input replacement,ProgressSink sink){Snapshot s=store.read(corpusId);if(s.documents().stream().noneMatch(d->d.id().equals(documentId)))throw new IllegalArgumentException("Unknown document");List<Input> inputs=new ArrayList<>();for(Document d:s.documents())if(!d.id().equals(documentId)){String text=s.passages().stream().filter(p->p.documentId().equals(d.id())).sorted(Comparator.comparingInt(Passage::ordinal)).map(Passage::text).reduce((a,b)->a+b.substring(Math.min(cfg.overlap(),b.length()))).orElse("");inputs.add(new Input(d.name(),"text/plain",text.getBytes(java.nio.charset.StandardCharsets.UTF_8),d.id()));}if(replacement!=null)inputs.add(new Input(replacement.name(),replacement.mediaType(),replacement.bytes(),documentId));store.save(s.status(Status.BUILDING,null,null));process(corpusId,inputs,sink);}
    public void removeSource(String corpusId,String documentId,ProgressSink sink){replaceSource(corpusId,documentId,null,sink);}
}
